def rearange_string(s):
    # Create a dictionary to store the frequency of each character
    freq = {}
    for char in s:
        if char in freq:
            freq[char] += 1
        else:
            freq[char] = 1

    # Create a list to store the frequency of adjacent characters
    adj_freq = []
    for i in range(len(s)-1):
        if s[i] == s[i+1]:
            adj_freq.append(freq[s[i]])
        else:
            adj_freq.append(freq[s[i]] + freq[s[i+1]])

    # Check if the frequency of adjacent characters is different
    if len(adj_freq) != len(set(adj_freq)):
        return False
    else:
        return True

