def smallest_missing(arr, start, end):
    if start == end:
        return start + 1
    if arr[start] != arr[start + 1]:
        return start + 1
    if arr[end] != arr[end - 1]:
        return end + 1
    if arr[start] == arr[start + 1] and arr[end] == arr[end - 1]:
        return start + 1
    if arr[start] == arr[start + 1]:
        return smallest_missing(arr, start + 1, end)
    if arr[end] == arr[end - 1]:
        return smallest_missing(arr, start, end - 1)
    if arr[start] == arr[start + 1] and arr[end] == arr[end - 1]:
        return end + 1
    if arr[start] == arr[start + 1]:
        return smallest_missing(arr, start + 1, end)
    if arr[end] == arr[end - 1]:
        return smallest_missing(arr, start, end - 1)
    return -1

